SELECT json_build_object(
 'table',(SELECT COALESCE(json_agg(json_build_object('kind',c.relkind,'persistence',c.relpersistence,'rowSecurity',c.relrowsecurity,'forcedRowSecurity',c.relforcerowsecurity,'ownerMatches',pg_get_userbyid(c.relowner)=CURRENT_USER)),'[]'::json) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname='SelectiveCompanyGeneration'),
 'columns',(SELECT COALESCE(json_agg(json_build_object('name',column_name,'type',data_type,'nullable',is_nullable,'default',column_default) ORDER BY ordinal_position),'[]'::json) FROM information_schema.columns WHERE table_schema='public' AND table_name='SelectiveCompanyGeneration'),
 'triggers',(SELECT COALESCE(json_agg(json_build_object('schema_name',n.nspname,'table_name',c.relname,'trigger_name',t.tgname,'enabled',t.tgenabled,'deferrable',t.tgdeferrable,'initially_deferred',t.tginitdeferred,'function_schema',pn.nspname,'function_name',p.proname,'definition',pg_get_triggerdef(t.oid)) ORDER BY t.tgname),'[]'::json) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_proc p ON p.oid=t.tgfoid JOIN pg_namespace pn ON pn.oid=p.pronamespace WHERE NOT t.tgisinternal AND (c.relname='SelectiveCompanyGeneration' OR t.tgname IN ('company_information_epoch','selected_company_no_truncate'))),
 'functions',(SELECT COALESCE(json_agg(json_build_object('name',p.proname,'schema',n.nspname,'arguments',pg_get_function_identity_arguments(p.oid),'returns',pg_get_function_result(p.oid),'language',l.lanname,'volatility',p.provolatile,'securityDefiner',p.prosecdef,'configuration',p.proconfig,'ownerMatches',pg_get_userbyid(p.proowner)=CURRENT_USER,'bodySha256',encode(sha256(convert_to(p.prosrc,'UTF8')),'hex')) ORDER BY p.proname),'[]'::json) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang WHERE n.nspname='public' AND p.proname IN ('fai_selected_company_generation','fai_selected_company_generation_guard','fai_selective_client_information_valid')),
 'constraints',(SELECT COALESCE(json_agg(json_build_object('name',c.conname,'definition',pg_get_constraintdef(c.oid),'validated',c.convalidated,'type',c.contype) ORDER BY c.conname),'[]'::json) FROM pg_constraint c WHERE c.conrelid=to_regclass('public."SelectiveCompanyGeneration"')),
 'clientConstraint',(SELECT COALESCE(json_agg(json_build_object('name',c.conname,'definition',pg_get_constraintdef(c.oid),'validated',c.convalidated,'type',c.contype) ORDER BY c.conname),'[]'::json) FROM pg_constraint c WHERE c.conrelid='public."SelectiveClientGrant"'::regclass AND c.conname='selective_client_payload_structure')
);
